        ("service", "k7radio wifi-service-start", 20, [b"WIFI shared start ret=0"]),
        ("probe", "k7voice probe", 15, [b"VOICE native_network=1"]),
        ("scan", "k7voice scan", 50, [b"VOICE scan_done"]),
    ]
    for stage in stages:
        results.append(run_stage(port, *stage))
finally:
