    if (typeof fetchImpl !== 'function') throw new TypeError('fetch_required');
    const parsed = new URL(requiredText(baseUrl, 'base_url', 2048));
    if (!['http:', 'https:'].includes(parsed.protocol)) throw new TypeError('base_url_invalid');
