"""Real brief report to bounded speech packets. No mock narration or AI additions."""
import asyncio
import json
import re
import uuid
import os
from .assessment_result import fetch_result
import httpx


def report_sentences(result):
    status = result['status']
    if status == 'needs_retake':
        names = {'front': '正面', 'left': '左侧', 'right': '右侧'}
        return ['照片需要重新拍摄。请补拍' + '、'.join(names[v] for v in result['requiredViews']) + '照片。']
    if status == 'failed':
        return ['本次皮肤检测未能完成，请查看检测失败信息。']
    if status == 'task_replaced':
        return ['本次检测已被新任务替换，请等待新任务的报告。']
    if status != 'report_ready':
        return ['报告仍在分析中，请稍后查询。']
    brief = result['brief']
    conclusion, description = brief.get('conclusion'), brief.get('description')
    if conclusion is not None and not isinstance(conclusion, str):
        raise ValueError('invalid_report_conclusion')
    if description is not None and not isinstance(description, str):
        raise ValueError('invalid_report_description')
    text = '皮肤检测报告已生成。'
    if conclusion:
        text += '报告结论为：' + conclusion + '。'
    if description:
        text += description
    else:
        text += '后端暂未提供详细说明。'
    if len(text) > 2400:
        raise ValueError('report_text_too_long')
    parts = []
    for sentence in re.split(r'(?<=[。！？；\n])', text):
        sentence = sentence.strip()
        parts.extend(sentence[i:i+80] for i in range(0, len(sentence), 80))
    return parts


async def deliver_report(auth, reader, writer, read_packet, packet, synthesize, base):
    kind, body = await read_packet(reader, 36)
    if kind != b'R' or len(body) != 36:
        raise ValueError('invalid_report_task')
    task_id = str(uuid.UUID(body.decode('ascii')))
    async def with_waits(awaitable):
        job = asyncio.create_task(awaitable)
        try:
            while not job.done():
                done, _ = await asyncio.wait({job}, timeout=5)
                if not done:
                    await packet(writer, b'W', b'')
            return await job
        finally:
            if not job.done():
                job.cancel()
            await asyncio.gather(job, return_exceptions=True)

    async with httpx.AsyncClient() as client:
        for attempt in range(60):
            result = await with_waits(fetch_result(auth, task_id, client))
            if result['status'] not in ('queued', 'analyzing'):
                break
            await packet(writer, b'W', b'')
            if attempt < 59:
                await asyncio.sleep(5)
        status = {k: v for k, v in result.items() if k != 'brief'}
        await packet(writer, b'J', json.dumps(status, ensure_ascii=False).encode())
        narration_mode = os.getenv('K7_REPORT_NARRATION_MODE', 'brief')
        if narration_mode not in ('brief', 'mock-sse', 'real-sse'):
            raise ValueError('invalid_narration_mode')
        async def text_source():
            if result['status'] == 'report_ready' and narration_mode != 'brief':
                from .report_narration import stream_sentences
                if narration_mode == 'mock-sse':
                    yield '以下为联调测试文案，不是真实测肤结果。'
                async for text in stream_sentences(auth, client, task_id, result['reportId']):
                    yield text
            else:
                for text in report_sentences(result): yield text
        audio = asyncio.Queue(maxsize=2)
        async def producer():
            try:
                async for text in text_source():
                    pcm, _ = await synthesize(base, text)
                    await audio.put(bytes(pcm))
                await audio.put(None)
            except Exception as exc:
                await audio.put(exc)
        producer_job = asyncio.create_task(producer())
        count = 0
        try:
            while True:
                pcm = await with_waits(audio.get())
                if pcm is None: break
                if isinstance(pcm, Exception): raise pcm
                # Check again after synthesis; a replaced task must never play its old report.
                fresh = await with_waits(fetch_result(auth, task_id, client))
                if fresh['status'] != result['status'] or fresh.get('reportId') != result.get('reportId'):
                    raise ValueError('report_changed_before_playback')
                await packet(writer, b'D', pcm)
                kind, body = await asyncio.wait_for(read_packet(reader, 0), 45)
                if kind != b'A' or body:
                    raise ValueError('report_playback_not_acknowledged')
                count += 1
        finally:
            if not producer_job.done(): producer_job.cancel()
            await asyncio.gather(producer_job, return_exceptions=True)
        await packet(writer, b'E', b'')
    return {'report_task_id': task_id, 'report_status': result['status'],
            'report_narration_mode': narration_mode, 'report_segments_played': count, 'completed': True}
"""Strict task-bound SSE delta adapter for the current backend narration contract."""
import json
import re
from urllib.parse import quote


async def sentences(lines, task_id, report_id):
    event = ''; data = []; sequence = 0; request_id = None; pending = ''; total = 0
    async for line in lines:
        if len(line) > 8192:
            raise ValueError('narration_line_too_long')
        if line.startswith(':'):
            continue
        if line:
            field, _, value = line.partition(':')
            if field == 'event': event = value.lstrip(' ')
            if field == 'data': data.append(value.lstrip(' '))
            if sum(map(len, data)) > 8192:
                raise ValueError('narration_event_too_long')
            continue
        if not data:
            event = ''; continue
        message = json.loads('\n'.join(data)); data = []
        sequence += 1
        if (type(message.get('seq')) is not int or message['seq'] != sequence or
            message.get('taskId') != task_id or message.get('reportId') != report_id):
            raise ValueError('narration_identity_or_sequence')
        if sequence == 1:
            request_id = message.get('requestId')
            if event != 'start' or not isinstance(request_id, str) or not request_id:
                raise ValueError('narration_missing_start')
        elif message.get('requestId') != request_id:
            raise ValueError('narration_request_changed')
        elif event == 'text_delta':
            delta = message.get('delta')
            if not isinstance(delta, str): raise ValueError('invalid_narration_delta')
            total += len(delta)
            if total > 6000: raise ValueError('narration_too_long')
            pending += delta
            while pending:
                match = re.search(r'[。！？；\n]', pending)
                length = min(match.end(), 80) if match else (80 if len(pending) >= 80 else 0)
                if not length: break
                text, pending = pending[:length].strip(), pending[length:]
                if text: yield text
        elif event == 'done':
            if pending.strip(): yield pending.strip()
            return
        else:
            raise ValueError('narration_error_or_invalid_event')
        event = ''
    raise ValueError('narration_incomplete')


async def stream_sentences(auth, client, task_id, report_id):
    token = await auth.session_token()
    url = auth.auth['base_url'].rstrip('/') + '/api/v1/skin-assessment-tasks/' + quote(task_id, safe='') + '/report-narration-stream'
    async with client.stream('GET', url, headers={'Authorization': 'Bearer ' + token},
                             timeout=30, follow_redirects=False) as response:
        response.raise_for_status()
        if not response.headers.get('content-type', '').startswith('text/event-stream'):
            raise ValueError('narration_not_sse')
        async for text in sentences(response.aiter_lines(), task_id, report_id):
            yield text
"""Three-view backend contract. No capture, motion, generated consent or retries."""
from dataclasses import dataclass
import hashlib
import json
import re
import uuid
from pathlib import Path
import httpx

VIEWS = ('front', 'left', 'right')

@dataclass(frozen=True)
class Submission:
    capture_session_id: str
    consent_evidence_ref: str
    idempotency_key: str
    photos: tuple

    @classmethod
    def create(cls, capture_session_id, consent_evidence_ref, photos, idempotency_key=None):
        for value in (capture_session_id, consent_evidence_ref):
            if not isinstance(value, str) or not value.strip() or len(value) > 128:
                raise ValueError('missing_capture_or_consent_reference')
        if set(photos) != set(VIEWS):
            raise ValueError('three_exact_views_required')
        copied = []
        for view in VIEWS:
            image = bytes(photos[view])
            if len(image) < 4 or len(image) > 10 * 1024 * 1024:
                raise ValueError('invalid_image_size')
            if not (image.startswith(b'\xff\xd8') and image.endswith(b'\xff\xd9')):
                raise ValueError('camera_jpeg_required')
            copied.append((view, image))
        key = idempotency_key if idempotency_key is not None else str(uuid.uuid4())
        if not isinstance(key,str) or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,128}',key):
            raise ValueError('invalid_idempotency_key')
        return cls(capture_session_id, consent_evidence_ref, key, tuple(copied))

    def manifest(self):
        return {'captureSessionId': self.capture_session_id,
                'consentEvidenceRef': self.consent_evidence_ref, 'photoVersion': '1',
                'idempotencyKey': self.idempotency_key,
                'views': {view: {'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
                          for view, data in self.photos}}

async def upload(client, base_url, session_token, submission):
    if not session_token or '\r' in session_token or '\n' in session_token:
        raise ValueError('invalid_session_token')
    metadata = {'photoVersion':'1', 'captureSessionId':submission.capture_session_id,
                'consentEvidenceRef':submission.consent_evidence_ref}
    parts = [('metadata',(None,json.dumps(metadata,ensure_ascii=False),'application/json'))]
    parts += [(view,(view+'.jpg',image,'image/jpeg')) for view,image in submission.photos]
    # The immutable submission and its original key must survive uncertain results.
    response = await client.post(base_url.rstrip('/')+'/api/v1/skin-assessment-tasks',
        headers={'Authorization':'Bearer '+session_token,'Idempotency-Key':submission.idempotency_key},
        files=parts, timeout=60, follow_redirects=False)
    if response.status_code not in (200,202):
        code='http_'+str(response.status_code)
        try:
            body=response.json(); error=body.get('error',{})
            if isinstance(error,dict) and isinstance(error.get('code'),str):code=error['code']
        except (ValueError,AttributeError):pass
        raise ValueError('assessment_upload_rejected:'+code)
    body=response.json();data=body.get('data',{})
    if not isinstance(data,dict) or data.get('status')!='queued' or data.get('photoVersion')!='1':
        raise ValueError('invalid_acceptance')
    try:uuid.UUID(data['taskId'])
    except (KeyError,ValueError,TypeError,AttributeError):raise ValueError('invalid_task_id')
    return {'accepted':True,'report_ready':False,'taskId':data['taskId'],
            'photoVersion':data['photoVersion'],'status':data['status'],
            'idempotencyKey':submission.idempotency_key}

def prepare_development_submission(capture_session_id, photos, idempotency_key=None, config_path=None):
    """Use the user's explicit development reference; never a production default."""
    path = Path(config_path) if config_path else Path(__file__).with_name('assessment-upload.dev.json')
    config = json.loads(path.read_text(encoding='utf-8'))
    if config.get('environment') != 'development':
        raise ValueError('development_config_required')
    submission = Submission.create(capture_session_id, config.get('consentEvidenceRef'), photos, idempotency_key)
    return config['baseUrl'], submission

