+  printf("K7CLOUD device intent=%u\n",(unsigned)intent);
+  if(intent==K7_VOICE_NONE){rc=0;goto done;}
+  if(intent==K7_VOICE_QUIET){rc=k7cloud_tts_control(1);goto done;}
+  if(intent==K7_VOICE_STOP)
