  if (channel == __atomic_load_n(&g_bt_pending_channel, __ATOMIC_ACQUIRE) &&
      __atomic_compare_exchange_n(&g_bt_pending, &pending, false, false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE))
